import {readFileSync,writeFileSync} from 'node:fs';
import assert from 'node:assert/strict';
import {ArcControlMemory} from '/home/holo/line/scripts/v0/optimizer/arc_memory.ts';
import {compileWorker} from '/home/holo/line/tools/parity/parity.ts';
const out='/tmp/engine-under7k-next-20261104',records:any[]=[];
const original=(ArcControlMemory.prototype as any).nearestControls;
const seen=new WeakMap<object,{id:number;values:Map<string,{rows:number;features:number[]}>}>();let nextId=0;
(ArcControlMemory.prototype as any).nearestControls=function*(features:number[],requested:number){
 let memory=seen.get(this);if(!memory){memory={id:nextId++,values:new Map()};seen.set(this,memory);}
 const finite=features.every(Number.isFinite),key=features.map(v=>Object.is(v,-0)?'-0':String(v)).join('|');
 const prior=memory.values.get(key);let consumed=0;
 try {for(const row of original.call(this,features,requested)){consumed++;yield row;}}
 finally {records.push({memory:memory.id,models:this.modelCount,rows:this.controls.length,requested,consumed,finite,repeated:!!prior,sameFeatureObject:prior?.features===features,localRowsChanged:prior!==undefined&&prior.rows!==this.controls.length});memory.values.set(key,{rows:this.controls.length,features});}
};
await compileWorker(61,out+'/retrieval-reuse-track.json');
const track=JSON.parse(readFileSync(out+'/retrieval-reuse-track.json','utf8')),expected=JSON.parse(readFileSync('/home/holo/line/tools/parity/cells.json','utf8')).cells[61];
assert.equal(track.trackHash,expected.trackHash);assert.equal(track.physicalFrames,expected.physicalFrames);
const sum=(predicate:(r:any)=>boolean)=>records.filter(predicate).reduce((n,r)=>n+r.models,0);
const result={description:'Untimed exact-query repetition diagnostic; forwards original retrieval and adaptation unchanged. Each memory instance has independent immutable model rows and changing local rows.',calls:records.length,memories:nextId,repeatedCalls:records.filter(r=>r.repeated).length,modelRows:sum(()=>true),repeatedModelRows:sum(r=>r.repeated),trackHash:track.trackHash,physicalFrames:track.physicalFrames,records};
writeFileSync(out+'/retrieval-reuse.json',JSON.stringify(result,null,2)+'\n');console.log({...result,records:undefined});

